// Parse Claude's JSON response and preserve ALL premium fields
const claudeResponse = $input.first().json;

// Get platform settings from webhook
const webhookData = $('Webhook Trigger').first().json;
const platforms = webhookData.body?.platforms || webhookData.platforms || [];

// Extract the response text from Claude
let responseText = '';
if (claudeResponse.content && Array.isArray(claudeResponse.content)) {
  // New Claude API format
  responseText = claudeResponse.content[0]?.text || '';
} else if (claudeResponse.text) {
  responseText = claudeResponse.text;
} else if (claudeResponse.response) {
  responseText = claudeResponse.response;
} else if (typeof claudeResponse === 'string') {
  responseText = claudeResponse;
}

// Try to parse JSON from the response
let postsData;
try {
  // Remove markdown code blocks if present
  let cleanedText = responseText.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  // Sanitize smart quotes and unicode that break JSON.parse
  cleanedText = cleanedText
    .replace(/[\u201c\u201d]/g, '"')
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/\u2014/g, '--')
    .replace(/\u2013/g, '-')
    .replace(/\u2026/g, '...')
    .replace(/\u00a0/g, ' ');
  postsData = JSON.parse(cleanedText);
} catch (error) {
  console.error('Failed to parse:', responseText);
  throw new Error('Failed to parse Claude response as JSON: ' + error.message);
}

// Extract posts array
let posts = [];
if (Array.isArray(postsData)) {
  posts = postsData;
} else if (postsData.posts && Array.isArray(postsData.posts)) {
  posts = postsData.posts;
} else {
  throw new Error('Could not find posts array in Claude response');
}

// Format each post - PRESERVE ALL FIELDS including premium ones
const formattedPosts = posts.map((post, index) => {
  // Find the platform settings for this post
  const platformSettings = platforms.find(p => p.name?.toLowerCase() === post.platform?.toLowerCase());
  const includeImages = platformSettings?.includeImages !== false; // Default true if not specified

  return {
    json: {
      // Original fields
      platform: post.platform || 'unknown',
      post_number: post.post_number || index + 1,
      caption: post.caption || '',
      hashtags: post.hashtags || '',

      // Add includeImages flag per platform
      includeImages: includeImages,

      // PREMIUM FIELDS - preserve from Claude response
      optimal_posting_time: post.optimal_posting_time || '',
      engagement_goal: post.engagement_goal || '',
      content_type: post.content_type || '',
      photo_keywords: post.photo_keywords || '',

      // Preserve any other fields Claude might return
      ...post
    }
  };
});


// Posting tip matrix based on studio_type + content format
const formData = $('Parse Form Data').first().json;
const studioType = formData.studio_type || 'general_fitness';
const tipMatrix = {
  yoga_pilates: { feed_post: 'Best for your audience: Tue/Thu 7 - 9am or Sun evening 6 - 8pm', reel: 'Best for your audience: Wed/Sat 7 - 9am', story: 'Best for your audience: Daily 6 - 8am or 8 - 10pm', thread: 'Best for your audience: Weekday mornings 6 - 9am' },
  hiit_crossfit: { feed_post: 'Best for your audience: Mon/Wed/Fri 6 - 8am or 6 - 8pm', reel: 'Best for your audience: Mon/Thu 5 - 7pm', story: 'Best for your audience: Daily 5 - 7am or 7 - 9pm', thread: 'Best for your audience: Mon morning 6 - 9am' },
  dance_barre: { feed_post: 'Best for your audience: Tue/Thu 12 - 2pm or 7 - 9pm', reel: 'Best for your audience: Fri evening or Sat morning', story: 'Best for your audience: Daily 8 - 10am or 8 - 10pm', thread: 'Best for your audience: Weekday afternoons 12 - 3pm' },
  martial_arts: { feed_post: 'Best for your audience: Tue/Thu 4 - 6pm or 7 - 9pm', reel: 'Best for your audience: Wed/Sat 4 - 7pm', story: 'Best for your audience: Daily 3 - 6pm', thread: 'Best for your audience: Weekday evenings 5 - 8pm' },
  general_fitness: { feed_post: 'Best for most fitness audiences: Mon/Wed/Fri 12pm or 7pm', reel: 'Best for most fitness audiences: Tue/Thu 6 - 9pm', story: 'Best for most fitness audiences: Daily 7 - 9am or 8 - 10pm', thread: 'Best for most fitness audiences: Weekday mornings 8 - 10am' }
};

formattedPosts.forEach(fp => {
  var format = fp.json.format || 'feed_post';
  var tips = tipMatrix[studioType] || tipMatrix.general_fitness;
  fp.json.postingTip = tips[format] || tips.feed_post || '';
  fp.json.studioType = studioType;
});


// Update content variety tracker on studio_accounts
try {
  const formData2 = $('Parse Form Data').first().json;
  const sid = formData2.studio_id;
  if (sid) {
    const newTypes = formattedPosts.map(p => p.json.content_type || 'unknown').filter(Boolean);
    const prevTypes = formData2.last_content_types || [];
    const merged = [...newTypes, ...prevTypes].slice(0, 5);
    const supaUrl2 = 'https://kidgcrqxrfcbsaeguwop.supabase.co';
    const svcKey2 = $vars.FCA_SUPABASE_SERVICE_KEY;
    await fetch(supaUrl2 + '/rest/v1/studio_accounts?id=eq.' + sid, {
      method: 'PATCH',
      headers: {
        apikey: svcKey2,
        Authorization: 'Bearer ' + svcKey2,
        'Content-Type': 'application/json',
        Prefer: 'return=minimal'
      },
      body: JSON.stringify({ last_content_types: merged })
    });
  }
} catch (e) {
  // Silent fail - variety tracking is non-critical
}

return formattedPosts;

// IMPROVED Smart Photo Matching - with photo_source routing
const post = $input.item.json;
const formData = $('Parse Form Data').first().json;
const photoSource = formData.photo_source || 'ai_assist';

// Safely get studio photos
let studioPhotos = [];
try {
  const photoNodes = $('Get Studio Photos').all();
  studioPhotos = Array.isArray(photoNodes) ? photoNodes : [];
} catch (e) {
  studioPhotos = [];
}

// CRITICAL: Track which photos have already been used
const workflowState = $getWorkflowStaticData('global');
if (!workflowState.usedPhotoIds) {
  workflowState.usedPhotoIds = [];
}

// Check if this platform wants images
const includeImages = post.includeImages !== false;
if (!includeImages) {
  return {
    ...post,
    photo_url: null,
    needs_ai_image: false,
    match_score: 0,
    skip_reason: 'Platform images disabled'
  };
}

// --- AI ONLY MODE: skip matching entirely, flag for AI generation ---
if (photoSource === 'ai_only') {
  return {
    ...post,
    photo_url: null,
    needs_ai_image: true,
    match_score: 0,
    match_reason: 'photo_source=ai_only - skipping studio matching, using AI generation'
  };
}

// --- STUDIO ONLY or AI ASSIST: attempt studio photo matching ---

function extractKeywords(post) {
  const keywords = [];
  if (post.photo_keywords) {
    const claudeKeywords = post.photo_keywords.toLowerCase().split(' ');
    claudeKeywords.forEach(kw => {
      if (kw.length > 2) keywords.push({ word: kw, weight: 20 });
    });
  }
  const caption = (post.caption || '').toLowerCase();
  const fitnessTerms = ['yoga', 'pilates', 'strength', 'cardio', 'hiit', 'barre',
    'cycling', 'spin', 'meditation', 'stretching', 'core', 'flexibility',
    'wellness', 'fitness', 'workout', 'training', 'class', 'studio',
    'instructor', 'beginner', 'advanced', 'intermediate', 'headshot', 'profile',
    'group', 'personal', 'session', 'member'];
  fitnessTerms.forEach(term => {
    if (caption.includes(term)) keywords.push({ word: term, weight: 10 });
  });
  const words = caption.split(' ').slice(0, 10);
  words.forEach(word => {
    if (word.length > 4 && !keywords.find(k => k.word === word)) {
      keywords.push({ word: word, weight: 5 });
    }
  });
  return keywords;
}

function scorePhoto(photo, weightedKeywords, caption) {
  let score = 0;
  const photoKeywords = (photo.keywords || '').toLowerCase();
  const photoTags = photo.tags || [];
  weightedKeywords.forEach(kw => {
    if (photoKeywords.includes(kw.word)) score += kw.weight;
  });
  if (Array.isArray(photoTags)) {
    photoTags.forEach(email => {
      const instructorName = email.split('@')[0].toLowerCase();
      if (caption.toLowerCase().includes(instructorName)) score += 25;
    });
  }
  return score;
}

const weightedKeywords = extractKeywords(post);
const caption = post.caption || '';

// FILTER OUT ALREADY-USED PHOTOS
const availablePhotos = studioPhotos.filter(photoItem => {
  return !workflowState.usedPhotoIds.includes(photoItem.json.id);
});

if (availablePhotos.length === 0) {
  return {
    ...post,
    photo_url: null,
    needs_ai_image: photoSource === 'ai_assist',
    match_score: 0,
    match_reason: studioPhotos.length === 0
      ? 'No photos in studio library'
      : 'All photos already used' + (photoSource === 'ai_assist' ? ' - falling back to AI' : ' - upload more or assign manually')
  };
}

let bestMatch = null;
let bestScore = 0;
availablePhotos.forEach(photoItem => {
  const photo = photoItem.json;
  const score = scorePhoto(photo, weightedKeywords, caption);
  if (score > bestScore) {
    bestScore = score;
    bestMatch = photo;
  }
});

if (bestScore >= 10 && bestMatch) {
  workflowState.usedPhotoIds.push(bestMatch.id);
  return {
    ...post,
    photo_url: bestMatch.photo_url,
    needs_ai_image: false,
    match_score: bestScore,
    matched_photo_id: bestMatch.id,
    matched_photo_name: bestMatch.file_name,
    match_reason: 'Matched with score ' + bestScore
  };
} else {
  return {
    ...post,
    photo_url: null,
    needs_ai_image: photoSource === 'ai_assist',
    match_score: bestScore,
    match_reason: photoSource === 'ai_assist'
      ? 'Best score ' + bestScore + ' below threshold - falling back to AI'
      : 'Best score ' + bestScore + ' below threshold - assign photo manually in dashboard'
  };
}

// Get the AI image URL from Gemini/Flux response via Trigger AI Photo
const geminiResponse = $input.item.json;
const aiImageUrl = geminiResponse.image_url || geminiResponse.url || null;

// Resolve the post that generated THIS specific image, pulling from Check Low Scores
// (the LIVE prompt-building node) which stashes the original post via _original AND
// carries the AI prompt sent to Gemini. Format Image Prompt is orphaned dead code and
// is NOT in the live execution path. Fallback to Smart Photo Matching for the post
// context if Check Low Scores isn't reachable for some reason.
let post = {};
let aiPrompt = null;
try {
  const checkItem = $('Check Low Scores').item;
  if (checkItem && checkItem.json) {
    aiPrompt = checkItem.json.prompt || null;
    post = checkItem.json._original || {};
  }
} catch (e) {
  // Silent fallthrough
}
if (!post || Object.keys(post).length === 0) {
  try {
    post = $('Smart Photo Matching').item?.json || {};
  } catch (e2) {
    post = {};
  }
}

// Attach the AI image URL and preserve the prompt on both fields.
// image_prompt = the prompt we built and sent to Gemini
// generation_prompt = mirror of image_prompt for the display layer contract
return {
  json: {
    ...post,
    photo_url: aiImageUrl,
    needs_ai_image: !aiImageUrl,
    match_reason: aiImageUrl ? 'AI generated via ' + (geminiResponse.model || 'gemini') : (post.match_reason || null),
    image_prompt: aiPrompt || post.image_prompt || null,
    generation_prompt: aiPrompt || post.generation_prompt || null
  }
};

const post = $input.item.json;
const formData = $('Parse Form Data').first().json;
const userPrompt = (formData.ai_photo_prompt || '').trim();
let caption = post.caption || '';

// Remove emojis, hashtags, mentions
caption = caption.replace(/[#@]/g, '');
caption = caption.replace(/#\w+/g, '');

// Remove CTAs
caption = caption.replace(/DM.*|Click.*|Link in bio.*|Join us.*|Book now.*|Tag a friend.*|Comment below.*/gi, '');

// Remove questions
caption = caption.replace(/\?.*$/g, '');

// Take first sentence only
caption = caption.split(/[.!]/)[0].trim();

// Camera profile classification
const t = caption.toLowerCase();
let profileType = 'lifestyle';
if (/portrait|headshot|instructor|trainer|coach|face|profile/i.test(t)) profileType = 'portrait';
else if (/action|jumping|running|hiit|boxing|crossfit|burpee|exercise|workout|sweat|moving/i.test(t)) profileType = 'action';
else if (/studio|interior|equipment|gym|facility|space|room|class setup/i.test(t)) profileType = 'studio';
else if (/food|meal|nutrition|smoothie|protein|snack|recipe|bowl|prep/i.test(t)) profileType = 'food';

const profiles = {
  portrait: 'Sony A7IV, 85mm f/1.4 lens. Rembrandt lighting with fill card, catchlights in eyes. ISO 200, 1/200s, f/1.4, shallow depth of field',
  action: 'Canon R5, 24-70mm f/2.8 lens. High-speed flash freeze, dramatic rim light. ISO 800, 1/2000s, f/2.8, peak action frozen',
  studio: 'Nikon Z8, 35mm f/1.8 lens. Three-point studio setup, key + fill + hair light, clean backdrop. ISO 100, 1/160s, f/5.6, even exposure',
  lifestyle: 'Sony A7RV, 50mm f/1.2 lens. Golden hour window light, warm ambient glow. ISO 400, 1/125s, f/1.2, creamy bokeh background',
  food: 'Canon R6 II, 90mm f/2.8 macro lens. Soft diffused overhead, white bounce below, no harsh shadows. ISO 200, 1/80s, f/4, tight focus on hero dish'
};

// Use ai_photo_prompt if provided, otherwise build default prompt
let imagePrompt;
if (userPrompt) {
  imagePrompt = userPrompt + '. Context: ' + caption + '. Photographed with ' + profiles[profileType] + '. Photorealistic, high-end fitness setting, clean composition, professional quality, natural colors, sharp focus.';
} else {
  imagePrompt = 'Professional fitness studio photography: ' + caption + '. Photographed with ' + profiles[profileType] + '. Photorealistic, high-end fitness setting, clean composition, professional quality, natural colors, sharp focus.';
}

return {
  ...post,
  image_prompt: imagePrompt,
  camera_profile: profileType
};

// Build Premium Prompt - Generate comprehensive marketing strategy prompt

// Get form data from Parse Form Data node
const formData = $('Parse Form Data').first().json;

// Safely get studio instructors
let studioInstructors = [];
try {
  studioInstructors = $('Get Studio Instructors').all() || [];
} catch (e) {
  studioInstructors = [];
}

// Enrich instructors with bio/specialties from clients table
if (studioInstructors.length > 0) {
  try {
    const studioId = $('Parse Form Data').first().json.studio_id;
    const supaUrl = 'https://kidgcrqxrfcbsaeguwop.supabase.co';
    const svcKey = $vars.FCA_SUPABASE_SERVICE_KEY;
    const clientIds = studioInstructors.map(i => i.json.client_id).filter(Boolean);
    if (clientIds.length > 0) {
      const idsParam = clientIds.map(id => '"' + id + '"').join(',');
      const res = await fetch(supaUrl + '/rest/v1/clients?id=in.(' + idsParam + ')&select=id,bio,specialties', {
        headers: { apikey: svcKey, Authorization: 'Bearer ' + svcKey }
      });
      const clients = await res.json();
      if (Array.isArray(clients)) {
        const clientMap = {};
        clients.forEach(c => { clientMap[c.id] = c; });
        studioInstructors.forEach(i => {
          const cid = i.json.client_id;
          if (cid && clientMap[cid]) {
            i.json.bio = clientMap[cid].bio || null;
            i.json.specialties = clientMap[cid].specialties || null;
          }
        });
      }
    }
  } catch (e) {
    // Silent fail  --  instructors will just lack bio/specialties
  }
}

// Safely get studio photos (may return empty for testing)
let studioPhotos = [];
try {
  const photoNodes = $('Get Studio Photos').all();
  studioPhotos = photoNodes || [];
} catch (e) {
  studioPhotos = [];
}

function getSeason() {
  const month = new Date().getMonth();
  if (month >= 2 && month <= 4) return 'Spring';
  if (month >= 5 && month <= 7) return 'Summer';
  if (month >= 8 && month <= 10) return 'Fall';
  return 'Winter';
}

function getOptimalLength(platform) {
  const lengths = {
    instagram: '125-150 characters (hook first)',
    facebook: '40-80 characters (short & engaging)',
    twitter: '71-100 characters (concise)',
    linkedin: '150-200 characters (professional)'
  };
  return lengths[platform] || '100-150 characters';
}

function getBestTimes(platform) {
  const times = {
    instagram: ['Monday 6:30 AM - Morning motivation', 'Wednesday 11 AM - Lunch break scroll', 'Friday 7 PM - Weekend planning'],
    facebook: ['Tuesday 9 AM - Coffee scroll', 'Thursday 1 PM - Afternoon break', 'Sunday 8 AM - Weekend motivation'],
    twitter: ['Monday 8 AM - Commute time', 'Wednesday 12 PM - Lunch engagement', 'Friday 5 PM - End of workweek'],
    linkedin: ['Tuesday 7 AM - Professional morning', 'Wednesday 12 PM - Business lunch', 'Thursday 5 PM - Career growth time']
  };
  return times[platform] || ['Morning (6-9 AM)', 'Lunch (12-1 PM)', 'Evening (6-8 PM)'];
}

function getEngagementStrategy(platform) {
  const strategies = {
    instagram: 'Ask for saves & shares. Encourage story replies. Use polls in captions.',
    facebook: 'Prompt comments with questions. Tag community members. Encourage event RSVPs.',
    twitter: 'Start conversations. Use threading. Engage with replies within 1 hour.',
    linkedin: 'Position as thought leader. Ask for professional insights. Share industry trends.'
  };
  return strategies[platform] || 'Encourage meaningful engagement and community building.';
}

function getInstagramFormatInstructions(format) {
  const formats = {
    feed_post: {
      label: 'Feed Post',
      structure: 'Hook > Value > CTA',
      instructions: '- Length: 150-300 words. Front-load the hook in the first line (shows before ...more).\n- Structure: Open with a scroll-stopping hook (question, bold claim, or relatable moment). Deliver 3-5 value points or a mini-story. Close with a clear CTA.\n- Tone: Confident, conversational, use line breaks for readability. Use emoji sparingly as visual anchors, not filler.\n- Hashtags: 15-20 relevant hashtags. Mix: 5 broad (#fitness), 5 niche (#reformerpilates), 5 local/branded.\n- Engagement: Ask a specific question to drive comments. Encourage saves with Save this for your next workout.'
    },
    story: {
      label: 'Story',
      structure: 'Quick, casual, interactive',
      instructions: '- Length: 1-2 short sentences max. Stories are consumed in <3 seconds.\n- Tone: Ultra-casual, emoji-heavy, behind-the-scenes energy. Write like texting a friend.\n- Interactive elements: ALWAYS include one: poll, quiz, question box, slider, or countdown sticker suggestion. Format like [POLL: Morning or evening workouts?] or [SLIDER: Rate your energy today].\n- Hashtags: 0-3 max, hidden behind stickers or in small text.\n- Content ideas: Quick tips, this or that polls, workout sneak peeks, instructor takeover moments, countdown to events.\n- Photo style: Prefer raw/candid over polished. Vertical 9:16 framing.'
    },
    thread: {
      label: 'Thread (Carousel alternative)',
      structure: 'Short punchy opinion > discussion',
      instructions: '- Length: 50-100 words. Punchy, opinionated, conversation-starting.\n- Tone: Hot take energy. Be bold, slightly provocative (but positive). Think unpopular fitness opinion or things your trainer wont tell you.\n- Structure: Lead with a strong opinion or surprising fact. Follow with 1-2 supporting points. End with Agree or disagree? or Drop your take below.\n- Hashtags: 0-3 max. Keep it clean and let the opinion drive engagement.\n- Goal: Maximize comments and debate. Feel like starting a conversation at the gym, not delivering a lecture.\n- Avoid: Long explanations, listicles, or educational deep-dives (save those for feed posts).'
    }
  };
  return formats[format] || formats.feed_post;
}

function getPlatformStrategy(platform) {
  const strategies = {
    facebook: 'FACEBOOK STRATEGY:\n- Tone: Warm, community-first, story-driven. Facebook audiences engage with emotion and relatability.\n- Length: 100-250 words. Longer posts perform well when they tell a story.\n- Structure: Personal story or member spotlight > community connection > soft CTA.\n- Hashtags: 3-5 max. Facebook deprioritizes hashtag-heavy posts.\n- Engagement: Ask open-ended questions. Use Tag someone who... prompts. Create event-style excitement.',
    twitter: 'TWITTER/X STRATEGY:\n- Tone: Sharp, witty, punchy. Every character counts.\n- Length: Under 280 characters per tweet. For threads: 3-5 tweets max.\n- Structure: Lead with the punchline, not the setup. One idea per tweet.\n- Hashtags: 1-2 max. Integrated naturally into the sentence, not appended.\n- Thread format: If postCount > 1, create a connected thread: tweet 1 = hook, tweets 2-4 = value, last tweet = CTA.\n- Engagement: Use Reply with... or RT if you... prompts.',
    linkedin: 'LINKEDIN STRATEGY:\n- Tone: Professional but human. Industry authority with personality. Avoid corporate jargon.\n- Length: 150-300 words. LinkedIn rewards longer, thoughtful posts.\n- Structure: Hook (first line shows in feed before see more) > Professional insight > Personal take > CTA.\n- Hashtags: 3-5 professional hashtags. #FitnessIndustry #WellnessBusiness style.\n- Engagement: Ask for professional opinions. What is your experience with...?\n- Position the studio as an industry leader. Share business insights, team culture, wellness trends.'
  };
  return strategies[platform] || '';
}

let instructorSection = '';
if (studioInstructors.length > 0) {
  const instructorList = studioInstructors.map(i => {
    const name = i.json.instructor_name || 'Instructor';
    const bio = i.json.bio || null;
    const specialties = i.json.specialties || null;
    let entry = `- ${name}`;
    if (bio) entry += `: ${bio}`;
    if (specialties) entry += `. Specialties: ${specialties}`;
    return entry;
  }).join('\n');
  instructorSection = `\n**Instructors at this studio:**\n${instructorList}\n\nRotate spotlight content evenly across instructors. Write in each instructor's voice based on their bio.`;
}

let photoContext = '';
if (studioPhotos.length > 0) {
  photoContext = `\n**Available Photos:** ${studioPhotos.length} professional photos in library\nWhen suggesting photo_keywords, use natural language like "headshot sara" or "yoga class wide shot"`;
} else {
  photoContext = `\n**No photos in library** - AI will generate professional fitness images as needed`;
}

const currentMonth = new Date().toLocaleDateString('en-US', { month: 'long' });
const currentSeason = getSeason();

const platformRequirements = formData.platforms.map(platform => {
  const name = typeof platform === 'string' ? platform : platform.name;
  const postCount = typeof platform === 'string' ? 3 : (platform.postCount || 3);
  const includeImages = typeof platform === 'string' ? true : (platform.includeImages !== false);
  const formats = typeof platform === 'object' && platform !== null ? (platform.formats || []) : [];

  const bestTimes = getBestTimes(name);
  const optimalLength = getOptimalLength(name);
  const engagementStrategy = getEngagementStrategy(name);

  let section = `\n**${name.toUpperCase()}** (${postCount} posts):\n- Optimal length: ${optimalLength}\n- Include images: ${includeImages ? 'YES' : 'NO'}\n- Best posting times: ${bestTimes.join(', ')}\n- Engagement strategy: ${engagementStrategy}`;

  if (name === 'instagram' && formats.length > 0) {
    section += `\n\n**Instagram Format Distribution:**\nDistribute the ${postCount} Instagram posts across these selected formats: ${formats.join(', ')}.`;
    formats.forEach(fmt => {
      const info = getInstagramFormatInstructions(fmt);
      section += `\n\n--- ${info.label.toUpperCase()} (format: "${fmt}") ---\nStructure: ${info.structure}\n${info.instructions}`;
    });
    if (formats.length > 1) {
      section += `\n\n**Distribution guidance:** Prioritize feed_post for value content, story for casual/interactive, thread for engagement/debate. If ${postCount} posts and ${formats.length} formats, ensure at least 1 post per format where possible.`;
    }
  }

  const platformStrat = getPlatformStrategy(name);
  if (platformStrat) {
    section += '\n\n' + platformStrat;
  }

  return section;
}).join('\n');

const totalPosts = formData.platforms.reduce((sum, p) => sum + (typeof p === 'string' ? 3 : (p.postCount || 3)), 0);
const hasFormats = formData.platforms.some(p => {
  const pName = typeof p === 'string' ? p : p.name;
  const pFormats = typeof p === 'object' && p !== null ? (p.formats || []) : [];
  return pName === 'instagram' && pFormats.length > 0;
});


// Content variety tracking
const lastTypes = formData.last_content_types || [];
let varietyInstruction = '';
if (lastTypes.length > 0) {
  varietyInstruction = '\n\n**CONTENT VARIETY RULE:**\nRecent content types generated for this studio: ' + lastTypes.join(', ') + '. Avoid repeating the same type consecutively. Prioritize variety across: motivational, instructor_spotlight, class_promo, educational_tip, behind_the_scenes, client_testimonial, challenge, seasonal.';
  if (lastTypes.length >= 2 && lastTypes[0] === lastTypes[1]) {
    varietyInstruction += ' The last 2 entries are both "' + lastTypes[0] + '"  --  you MUST choose a different content_type this time.';
  }
}

