  '<div style="color:{{brand_color}};font-size:24px;font-weight:700;line-height:1;">{{post_count}}</div>' +
  '<div style="color:#A0A0A0;font-size:12px;margin-top:6px;text-transform:uppercase;letter-spacing:0.05em;">{{post_word_caps}}</div>' +
  '</td>' +
  '<td width="33%" align="center" style="padding:20px 8px;background:rgba(255,255,255,0.02);border-top:1px solid #2A2A2A;border-bottom:1px solid #2A2A2A;">' +
  '<div style="color:{{brand_color}};font-size:24px;font-weight:700;line-height:1;">{{platform_count}}</div>' +
  '<div style="color:#A0A0A0;font-size:12px;margin-top:6px;text-transform:uppercase;letter-spacing:0.05em;">{{platform_word_caps}}</div>' +
  '</td>' +
  '<td width="34%" align="center" style="padding:20px 8px;background:rgba(255,255,255,0.02);border:1px solid #2A2A2A;border-radius:0 8px 8px 0;">' +
  '<div style="color:{{brand_color}};font-size:15px;font-weight:700;line-height:1.3;">{{week_big}}</div>' +
  '<div style="color:#A0A0A0;font-size:12px;margin-top:6px;text-transform:uppercase;letter-spacing:0.05em;">Week</div>' +
  '</td>' +
  '</tr></table>' +
  // CTA button
  '<table cellpadding="0" cellspacing="0" style="margin:0 0 28px;"><tr><td style="background:{{brand_color}};border-radius:8px;">' +
  '<a href="{{dashboard_url}}" style="display:inline-block;padding:14px 32px;color:#FFFFFF;text-decoration:none;font-weight:600;font-size:14px;">Review Your Content →</a>' +
  '</td></tr></table>' +
  // Divider + small print
  '<div style="height:1px;background:#2A2A2A;margin:0 0 20px;"></div>' +
  '<p style="color:#A0A0A0;font-size:13px;line-height:1.6;margin:0;">FCA creates content suggestions — you decide what to post and where. Review everything before publishing.</p>' +
  '</td></tr>' +
  // Footer
  '<tr><td style="background:#0F0F0F;padding:24px 0;text-align:center;">' +
  '<p style="color:#555555;font-size:12px;margin:0 0 8px;">FCA creates content suggestions — you decide what to post and where.</p>' +
  '<p style="color:#555555;font-size:12px;margin:0;">Fiorsaoirse LLC · <a href="{{unsubscribe_url}}" style="color:#555555;">Unsubscribe</a></p>' +
  '</td></tr>' +
  '</table></td></tr></table></body></html>';

// Substitution via split/join (safer than regex — no metachar escaping needed).
const renderedHtml = template
  .split('{{brand_color}}').join(brandColor)
  .split('{{post_count}}').join(String(postCount))
  .split('{{post_word}}').join(postWord)
  .split('{{post_word_caps}}').join(postWordCaps)
  .split('{{platform_count}}').join(String(platformCount))
  .split('{{platform_word_caps}}').join(platformWordCaps)
  .split('{{platforms}}').join(platformsLabel)
  .split('{{week_big}}').join(weekBig)
  .split('{{dashboard_url}}').join(dashboardUrl)
  .split('{{unsubscribe_url}}').join(unsubscribeUrl);

const subject = 'Your content is ready — ' + studioName;

return {
  json: {
    studio_id: studioId,
    studio_name: studioName,
    email: recipientEmail,
    delivery_id: deliveryId,
    brand_color: brandColor,
    post_count: postCount,
    platform_count: platformCount,
    platforms: platformsLabel,
    week_label: weekLabel,
    subject: subject,
    renderedHtml: renderedHtml
  }
};
